INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)', 'Renewable one-year term life insurance cover for bank/post office account holders aged 18-50, covering death from any cause', 'Department of Financial Services, Ministry of Finance', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Renewable one-year term life insurance cover for bank/post office account holders aged 18-50, covering death from any cause', 'Rs 2 lakh life cover on death of the insured due to any cause; annual premium Rs 330', 'https://www.jansuraksha.gov.in', 'https://www.jansuraksha.gov.in', TRUE, 'https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1922622&reg=48&lang=2', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Janani Suraksha Yojana (JSY)', 'Cash assistance to pregnant women for institutional delivery to reduce maternal and infant mortality; amount varies by state performance category (LPS/HPS) and rural/urban residence', 'Ministry of Health and Family Welfare (National Health Mission)', (SELECT category_id FROM scheme_categories WHERE category_name = 'Healthcare'), NULL, 'Cash assistance to pregnant women for institutional delivery to reduce maternal and infant mortality; amount varies by state performance category (LPS/HPS) and rural/urban residence', 'Rs 1400 (LPS rural), Rs 1000 (LPS urban), Rs 700 (HPS rural), Rs 600 (HPS urban), plus ASHA facilitation incentive', 'https://nhm.gov.in', 'https://nhm.gov.in/index1.php?lang=1&level=3&lid=309&sublinkid=841', TRUE, 'https://nhm.gov.in/WriteReadData/l892s/97827133331523438951.pdf', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Pradhan Mantri Kisan Maandhan Yojana (PM-KMY)', 'Voluntary and contributory pension scheme for small and marginal farmers, providing an assured minimum pension after age 60', 'Ministry of Agriculture and Farmers Welfare', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Voluntary and contributory pension scheme for small and marginal farmers, providing an assured minimum pension after age 60', 'Rs 3000/month pension after age 60; 50% family pension to spouse on death of farmer; monthly contribution Rs 55-200 matched by Government', 'https://maandhan.in/scheme/pmkmy', 'https://maandhan.in', TRUE, 'https://pmkisan.gov.in/Documents/PM-KMY%20-%20Salient%20Features.pdf', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('PM Krishi Sinchayee Yojana - Per Drop More Crop (PMKSY-PDMC)', 'Financial assistance for installation of micro-irrigation (drip and sprinkler) systems to improve water use efficiency at farm level', 'Ministry of Agriculture and Farmers Welfare (in coordination with Ministry of Jal Shakti)', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), NULL, 'Financial assistance for installation of micro-irrigation (drip and sprinkler) systems to improve water use efficiency at farm level', '55% subsidy for small and marginal farmers, 45% subsidy for other farmers on micro-irrigation installation cost', 'https://pmksy.gov.in', 'https://pmksy.gov.in', TRUE, 'https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1985487&reg=48&lang=2', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Soil Health Card Scheme', 'Free soil testing with crop-wise nutrient and fertilizer recommendations issued to land-holding farmers periodically to improve productivity', 'Ministry of Agriculture and Farmers Welfare', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), NULL, 'Free soil testing with crop-wise nutrient and fertilizer recommendations issued to land-holding farmers periodically to improve productivity', 'Free of cost soil testing and advisory card, reissued approximately every 2-3 years', 'https://soilhealth.dac.gov.in', 'https://soilhealth.dac.gov.in', TRUE, 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2104403&reg=48&lang=2', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Kisan Credit Card (KCC) Scheme', 'Single-window short-term credit facility for crop cultivation and allied agricultural needs (dairy, poultry, fisheries, animal husbandry) at subsidised interest rate via a RuPay-enabled card', 'Ministry of Agriculture and Farmers Welfare / Department of Financial Services', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), NULL, 'Single-window short-term credit facility for crop cultivation and allied agricultural needs (dairy, poultry, fisheries, animal husbandry) at subsidised interest rate via a RuPay-enabled card', 'Loan limit up to Rs 5 lakh eligible for interest subvention (effective 4% on timely repayment); collateral-free lending up to Rs 2 lakh', 'https://www.myscheme.gov.in/schemes/kcc', 'https://www.myscheme.gov.in/schemes/kcc', TRUE, 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=1808328&reg=3&lang=2', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Paramparagat Krishi Vikas Yojana (PKVY)', 'Cluster-based support for farmers to adopt organic farming, covering inputs, certification, processing and marketing end-to-end', 'Ministry of Agriculture and Farmers Welfare', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), NULL, 'Cluster-based support for farmers to adopt organic farming, covering inputs, certification, processing and marketing end-to-end', 'Rs 31500/hectare over 3 years per organic cluster, of which Rs 15000/hectare is direct DBT to farmers for inputs', 'https://pgsindia-ncof.gov.in', 'https://pgsindia-ncof.gov.in', TRUE, 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2099756', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('National Livestock Mission', 'Capital subsidy support for entrepreneurship development in rural poultry, sheep/goat breeding, piggery breeding, and feed/fodder production for individuals, FPOs, SHGs, JLGs and Section 8 companies', 'Ministry of Fisheries, Animal Husbandry and Dairying (Department of Animal Husbandry and Dairying)', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), NULL, 'Capital subsidy support for entrepreneurship development in rural poultry, sheep/goat breeding, piggery breeding, and feed/fodder production for individuals, FPOs, SHGs, JLGs and Section 8 companies', '50% capital subsidy: up to Rs 25 lakh (rural poultry), Rs 50 lakh (sheep/goat breeding farm), Rs 30 lakh (piggery breeding farm)', 'https://nlm.udyamimitra.in', 'https://dahd.gov.in/schemes/programmes/national_livestock_mission', TRUE, 'https://dahd.gov.in/sites/default/files/2023-11/NLMGuidelinesFinalApprovedByEC.pdf', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Pradhan Mantri Bhartiya Janaushadhi Pariyojana (PMBJP)', 'Quality generic medicines and surgical items sold at affordable prices to the public through dedicated Jan Aushadhi Kendras across the country', 'Department of Pharmaceuticals, Ministry of Chemicals and Fertilizers', (SELECT category_id FROM scheme_categories WHERE category_name = 'Healthcare'), NULL, 'Quality generic medicines and surgical items sold at affordable prices to the public through dedicated Jan Aushadhi Kendras across the country', 'Medicines priced 50-90% below branded market price; over 19500 Jan Aushadhi Kendras operational nationwide', 'https://janaushadhi.gov.in', 'https://janaushadhi.gov.in', TRUE, 'https://janaushadhi.gov.in/pmjy.aspx', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Nikshay Poshan Yojana', 'Monthly nutritional support cash transfer to all notified tuberculosis patients for the duration of their treatment under the National TB Elimination Programme', 'Ministry of Health and Family Welfare (Central TB Division)', (SELECT category_id FROM scheme_categories WHERE category_name = 'Healthcare'), NULL, 'Monthly nutritional support cash transfer to all notified tuberculosis patients for the duration of their treatment under the National TB Elimination Programme', 'Rs 1000 per month per notified TB patient, disbursed via DBT to Aadhaar-linked bank account', 'https://nikshay.in', 'https://tbcindia.mohfw.gov.in', TRUE, 'https://tbcindia.mohfw.gov.in/wp-content/uploads/2023/05/6851513623Nutrition-support-DBT-Scheme-details.pdf', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Rashtriya Arogya Nidhi (RAN)', 'Financial assistance to patients from Below Poverty Line families suffering from major life-threatening diseases (heart, kidney, liver, cancer, etc.) for treatment at government super-specialty hospitals', 'Ministry of Health and Family Welfare', (SELECT category_id FROM scheme_categories WHERE category_name = 'Healthcare'), NULL, 'Financial assistance to patients from Below Poverty Line families suffering from major life-threatening diseases (heart, kidney, liver, cancer, etc.) for treatment at government super-specialty hospitals', 'Financial assistance up to Rs 15 lakh (up to Rs 20 lakh for rare diseases)', 'https://mohfw.gov.in', 'https://mohfw.gov.in', TRUE, 'https://mohfw.gov.in/sites/default/files/7845192051425018860%20(1).pdf', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Pradhan Mantri Jan Dhan Yojana', 'Zero-balance basic savings bank deposit account with RuPay debit card, accident insurance cover, and overdraft facility for financial inclusion', 'Department of Financial Services, Ministry of Finance', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Zero-balance basic savings bank deposit account with RuPay debit card, accident insurance cover, and overdraft facility for financial inclusion', 'Accident insurance cover of Rs. 2 lakh (Rs. 1 lakh for accounts opened before 28.8.2018); overdraft facility up to Rs. 10,000', 'https://pmjdy.gov.in/', 'https://pmjdy.gov.in/', TRUE, 'https://pmjdy.gov.in/scheme', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('National Pension System', 'Voluntary defined-contribution pension account offering market-linked returns and tax benefits for retirement savings', 'Department of Financial Services, Ministry of Finance (PFRDA)', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Voluntary defined-contribution pension account offering market-linked returns and tax benefits for retirement savings', 'Market-linked returns; tax deduction up to Rs. 2 lakh under Section 80CCD', 'https://enps.nsdl.com/', 'https://financialservices.gov.in/national-pension-system', TRUE, 'https://financialservices.gov.in/national-pension-system', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Pradhan Mantri Garib Kalyan Anna Yojana', 'Free additional foodgrains to NFSA ration card holders under Antyodaya Anna Yojana (AAY) and Priority Household (PHH) categories', 'Department of Food and Public Distribution, Ministry of Consumer Affairs, Food and Public Distribution', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Free additional foodgrains to NFSA ration card holders under Antyodaya Anna Yojana (AAY) and Priority Household (PHH) categories', '5 kg foodgrain per person per month, free of cost', 'https://dfpd.gov.in/pradhan-mantri-garib-kalyan-anna-yojana/en', 'https://dfpd.gov.in/pradhan-mantri-garib-kalyan-anna-yojana/en', TRUE, 'https://dfpd.gov.in/pradhan-mantri-garib-kalyan-anna-yojana/en', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('One Nation One Ration Card', 'Portability of NFSA ration card foodgrain entitlement, allowing beneficiaries to draw rations from any Fair Price Shop in India via Aadhaar/biometric authentication', 'Department of Food and Public Distribution, Ministry of Consumer Affairs, Food and Public Distribution', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), NULL, 'Portability of NFSA ration card foodgrain entitlement, allowing beneficiaries to draw rations from any Fair Price Shop in India via Aadhaar/biometric authentication', 'As per existing ration card entitlement (AAY/PHH quota)', 'https://mahafood.gov.in/en/scheme/one-nation-one-ration-card/', 'https://mahafood.gov.in/en/scheme/one-nation-one-ration-card/', TRUE, 'https://mahafood.gov.in/en/scheme/one-nation-one-ration-card/', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Sanjay Gandhi Niradhar Anudan Yojana', 'Monthly financial assistance (pension) to destitute persons, orphans, disabled individuals, and other vulnerable categories without means of support', 'Social Justice & Special Assistance Department, Government of Maharashtra', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), 'Maharashtra', 'Monthly financial assistance (pension) to destitute persons, orphans, disabled individuals, and other vulnerable categories without means of support', 'Rs. 1,500 per month', 'https://sas.mahait.org/', 'https://sjsa.maharashtra.gov.in/en/scheme/sanjay-gandhi-niradhar-anudan-yojana/', TRUE, 'https://sjsa.maharashtra.gov.in/en/scheme/sanjay-gandhi-niradhar-anudan-yojana/', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Manodhairya Yojana', 'Financial assistance and rehabilitation support (shelter, medical, legal aid, counselling) to victims of rape, child sexual abuse, and acid attacks', 'Women and Child Development Department, Government of Maharashtra', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), 'Maharashtra', 'Financial assistance and rehabilitation support (shelter, medical, legal aid, counselling) to victims of rape, child sexual abuse, and acid attacks', 'Rs. 1 lakh to Rs. 10 lakh depending on severity of the case (as per revised 2024 Government Resolution)', 'https://womenchild.maharashtra.gov.in/', 'https://womenchild.maharashtra.gov.in/', TRUE, 'https://legalservices.maharashtra.gov.in/scheme/revised-manodhairya-yojana-gr-dated-01st-january-2024/', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Lek Ladki Yojana', 'Direct financial assistance to a girl child born in yellow/orange ration card families, disbursed in phases from birth until she turns 18', 'Women and Child Development Department, Government of Maharashtra', (SELECT category_id FROM scheme_categories WHERE category_name = 'Financial Aid'), 'Maharashtra', 'Direct financial assistance to a girl child born in yellow/orange ration card families, disbursed in phases from birth until she turns 18', 'Total Rs. 1,01,000 disbursed in phases from birth to age 18', 'https://womenchild.maharashtra.gov.in/', 'https://womenchild.maharashtra.gov.in/', TRUE, 'https://www.zpbeed.gov.in/en/scheme/lek-ladki-yojana/', '2026-09-14');
INSERT INTO schemes (name, description, ministry, category_id, state, benefit_summary, benefit_amount, application_url, official_portal, is_active, source_url, verified_at) VALUES ('Namo Shetkari Mahasanman Nidhi Yojana', 'Additional annual income support to PM-KISAN registered cultivable-landholding farmer families in Maharashtra', 'Department of Agriculture, Government of Maharashtra', (SELECT category_id FROM scheme_categories WHERE category_name = 'Agriculture'), 'Maharashtra', 'Additional annual income support to PM-KISAN registered cultivable-landholding farmer families in Maharashtra', 'Rs. 6,000 per year (Rs. 2,000 x 3 instalments), in addition to PM-KISAN\'s Rs. 6,000/year', 'https://nsmny.mahait.org/', 'https://nsmny.mahait.org/', TRUE, 'https://nsmny.mahait.org/', '2026-09-14');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)'), 'occupation', '=', 'Farmer', 'Applicant must be a landholding farmer engaged in agriculture', 'farmers enrolling in the scheme should have their own farmland and must be engaged in agriculture');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Ayushman Bharat Pradhan Mantri Jan Arogya Yojana (PM-JAY)'), 'is_bpl', '=', 'TRUE', 'Household must be identified as deprived/vulnerable per SECC 2011 census (broadly BPL-equivalent), not based on income tax returns', 'Eligibility is based on the Socio-Economic Caste Census (SECC) 2011 data... families living in kutcha houses with only one room... are eligible');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Awas Yojana - Urban (PMAY-U 2.0)'), 'annual_income', '<=', '900000', 'Household annual income must not exceed ₹9 lakh (covers EWS up to ₹3 lakh, LIG up to ₹6 lakh, MIG up to ₹9 lakh) under PMAY-U 2.0', 'EWS: Up to ₹3 lakh; LIG: Up to ₹6 lakh; MIG: Up to ₹9 lakh');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Post-Matric Scholarship for SC Students'), 'category', '=', 'SC', 'Applicant must belong to the Scheduled Caste community', 'Post Matric Scholarship covers... students from SC... categories');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Post-Matric Scholarship for SC Students'), 'annual_income', '<=', '250000', 'Family income must not exceed ₹2.5 lakh per year', 'The family income limit is INR 2.5 lakh per year in all four schemes for most Post-Matric scholarships');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Post-Matric Scholarship for SC Students'), 'education_level', '=', 'Post-Matric', 'Student must be studying in Class 11 or above (post-matriculation)', 'Students who have passed Class 10 and are studying in Class 11 or Class 12 can apply for Post-Matric scholarships');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pre-Matric Scholarship for Minorities'), 'is_minority', '=', 'TRUE', 'Applicant must belong to a notified minority community (Muslim, Sikh, Christian, Buddhist, Parsi, Jain)', 'Applicants must belong to a minority community as notified by the Government of India');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pre-Matric Scholarship for Minorities'), 'annual_income', '<=', '100000', 'Family income must not exceed ₹1 lakh per year', 'The annual family income of the candidate\'s parents/guardian should not exceed INR 1 lakh');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pre-Matric Scholarship for Minorities'), 'education_level', '=', 'Class 1-10', 'Student must be studying in Class 1 to Class 10', 'Candidates must be studying in class 1 to 10 in a government or private school');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Prime Minister\'s Employment Generation Programme (PMEGP)'), 'age', '>=', '18', 'Applicant must be at least 18 years old; no maximum age limit', 'Applicants should be minimum 18 years of age and there is no maximum age limit');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Sukanya Samriddhi Yojana'), 'gender', '=', 'FEMALE', 'Account can only be opened in the name of a girl child', 'for the welfare of a girl child');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Sukanya Samriddhi Yojana'), 'age', '<=', '10', 'Account must be opened for the girl child between birth and 10 years of age', 'account can be opened any time from the birth of the girl child until she attains 10 years of age');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Atal Pension Yojana'), 'age', '>=', '18', 'Subscriber must be at least 18 years old to join', 'Any Indian citizen between 18 and 40 years of age with a savings account can join');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Atal Pension Yojana'), 'age', '<=', '40', 'Subscriber must not be older than 40 years to join', 'Any Indian citizen between 18 and 40 years of age with a savings account can join');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Ujjwala Yojana (PMUY 2.0)'), 'gender', '=', 'FEMALE', 'LPG connection is provided in the name of an adult woman of the household', 'adult woman belonging to a poor household... is eligible');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Ujjwala Yojana (PMUY 2.0)'), 'age', '>=', '18', 'Applicant woman must have attained 18 years of age', 'the applicant must be an adult woman who has attained 18 years of age');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Ujjwala Yojana (PMUY 2.0)'), 'is_bpl', '=', 'TRUE', 'Household must belong to BPL/SECC-listed poor household categories', 'adult women aged 18+ from BPL households... belong to SECC 2011 list or eligible categories');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Stand-Up India'), 'age', '>=', '18', 'Applicant must be above 18 years of age', 'Applicants must be SC/ST and/or woman entrepreneur, above 18 years of age');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Stand-Up India'), 'category', 'IN', 'SC,ST', 'Scheme targets SC/ST entrepreneurs (women entrepreneurs of any category are separately eligible; see scheme description)', 'Applicants must be SC/ST and/or woman entrepreneurs');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri MUDRA Yojana (PMMY)'), 'age', '>=', '18', 'Borrower must be at least 18 years old', 'Eligible borrowers include Indian citizens aged 18-65 engaged in non-farm income-generating activities');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri MUDRA Yojana (PMMY)'), 'age', '<=', '65', 'Borrower must not be older than 65 years', 'Eligible borrowers include Indian citizens aged 18-65 engaged in non-farm income-generating activities');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Matru Vandana Yojana (PMMVY)'), 'gender', '=', 'FEMALE', 'Benefit is for pregnant women and lactating mothers', 'All pregnant women and lactating mothers... can get the scheme benefit');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Matru Vandana Yojana (PMMVY)'), 'age', '>=', '19', 'Pregnant woman must be at least 19 years of age', 'The pregnant woman must be at least 19 years of age or older');
INSERT INTO eligibility_rules (scheme_id, attribute_name, operator, value, rule_description, source_text_snippet) VALUES ((SELECT scheme_id FROM schemes WHERE name = 'Pradhan Mantri Fasal Bima Yojana (PMFBY)'), 'occupation', '=', 'Farmer', 'Applicant must be a farmer/cultivator or sharecropper growing notified crops', 'Eligible farmers include landowners, tenants, and sharecroppers growing notified crops');
